"""Build a source-reading seminar; cited data remain separate from editorial analysis."""
from pathlib import Path
import json, html, re, sys

R=Path(__file__).resolve().parents[1]
E=lambda s:html.escape(str(s),quote=True)
corpus=json.loads((R/'data/enshu-gunshi-corpus.json').read_text(encoding='utf-8'))['records']
fpjd=json.loads((R/'data/c006-fpjd.json').read_text(encoding='utf-8'))
fby={r['id']:r for r in fpjd['records']}

def gunshi(*forms):
    rows=[r for r in corpus if r['form'] in forms]
    assert set(forms)=={r['form'] for r in rows}
    return table(['原表記','対応する意味','1921年の記録地','原資料'],[
        [f'<a href="/enshu/records/#{r["id"]}">{E(r["form"])}</a>',E(r['gloss'])+(f'<small>{E(r["note"])}</small>' if r['note'] else ''),E(r['village']),f'<a href="https://dl.ndl.go.jp/pid/965680/1/{r["frame"]}">{r["page"]}頁 ↗</a>'] for r in rows])

def table(head,rows):
    return '<div class="seminar-table" tabindex="0" role="region" aria-label="横にスクロールできる比較表"><table><thead><tr>'+''.join(f'<th scope="col">{E(h)}</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<th scope="row">{c}</th>' if i==0 else f'<td>{c}</td>' for i,c in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'

def responses(*ids):
    rows=[]
    for rid in ids:
        r=fby[str(rid)]
        rows.append([E(r['item']),f'<a href="/c172#fpjd-{r["id"]}">{E(r["form"])}</a>',E(r['note']) or '注記なし'])
    return table(['調査項目','磐田市1地点の回答語形','原データの注記'],rows)

def cite(sid,label):return f'<a class="seminar-cite" href="#source-{sid}">{label}</a>'
G=cite('gunshi','［資料1：1242–1254頁］')
F=cite('fpjd','［資料2：回答データ・凡例］')
M=cite('mondo','［研究3：§3.1・4.2、図1–8］')
H=cite('hirako','［研究4：§2.1、368–369頁］')
K=cite('kumagai','［研究5：18–21頁・表1］')
T=cite('mingu','［資料6：民具と聞き取り］')

lessons=[]
def lesson(key,title,deck,body,question,answer):
    lessons.append({'id':key,'title':title,'deck':deck,'body':body,'question':question,'answer':answer})

lesson('evidence','「何語あるか」の前に、何を数えるか',
       '語形・語義・記録を分ける、方言資料批判の入口。',f'''
<h3>資料に書かれた単位を、分析の単位へ直結させない</h3>
<p>本サイトの郡誌選録は380記録・376種類の原表記です。「記録」は表記・意味・記録地・頁を一組にした行、「原表記」は文字列を重複除去したものです。どちらも、そのまま遠州弁の独立した語彙の総数にはなりません。異なる形が同じ意味に対応することも、同じ形が別の意味に対応することもあるからです。{G}</p>
{gunshi('つよ','おちのこ','ちやのこ')}
<p>福島村の「つよ」は露と杖の別行です。表記を検索キーにすると一つ、意味との対応を見ると二つになります。一方、袋井町の「おちのこ」「ちやのこ」は、ともに朝飯に対応します。二つの語形の記録があることは分かりますが、一人の話者が場面に応じて両方を使ったかまでは分かりません。ここに語彙体系を考えるための問いがあります。</p>
<h3>郡誌・調査票・教材は、証拠としての働きが違う</h3>
<p>郡誌の刊行年は1921年です。それを全項目の発話採録年と同一視せず、まず刊行された記録として扱います。対してFPJDは調査項目に対する回答を残し、同じ質問への複数回答や調査者の注記を持ちます。掲載287回答は211質問への回答を含み、「287人が使った」という意味ではありません。{F}</p>
<p>学び舎の作例は、意味を理解するために編集部が構成した教材です。資料から引いた語形と、編集した文を区別すれば、作例を歴史的な実例と取り違えずに利用できます。引用の単位を「ことば」だけで終えず、誰の、いつの、どの方法による記録かまで戻すのが、この講座の基本手順です。</p>
''','380記録から376原表記になった差を、誤記や重複の失敗と考えてよいでしょうか？',
'いいえ。同じ表記でも意味や記録地が違う行を残しています。文字列の種類数と資料上の記録数は、目的の違う集計です。独立した語の数を論じるには、同音異義・異形・意味の関係を別途検討します。')

lesson('geography','遠州のことばに、一本の境界線を引けるか',
       '記録地点と等語線から考える、地域差の読み方。',f'''
<h3>行政区域と、言語現象の広がりを分ける</h3>
<p>方言を地域で説明するとき、「遠州だから同じ」とまとめる前に、比較する現象を定めます。ある道具の呼び名、否定形、アクセントでは、広がり方が一致するとは限りません。一つの言語的特徴の分布を区切る線を等語線と呼びます。いくつもの線が重なるかどうかを確かめて初めて、方言区画の議論へ進めます。</p>
{gunshi('けあめ','けんけあめ','かたる')}
<p>上表では小雨に対応する形が袋井町と浅羽村で異なります。しかし、この二行だけで両地域の境に語形が切り替わる線は引けません。中間地点を含む調査がなく、記載のない場所で使わなかったとも言えないためです。「かたる」の二記録も、語形が共通することと意味の一致を切り分ける材料になります。{G}</p>
<h3>分布図を読むときの三つの照合</h3>
<p>第一に質問が同じかを見ます。同じ対象を別の説明で尋ねると、違う答えを引き出す可能性があります。第二に調査時期と話者の条件を見ます。第三に記号の意味を読みます。複数回答、未調査、無回答を、語形が存在しない地点と混同しないことが重要です。</p>
<p>全国資料には『方言文法全国地図』があります。1979–1982年に807地点で267項目を調べ、地図としては350図が刊行されています。項目数と地図数は別の単位です。高年層の土地生え抜きの男性を中心とする調査の分布を、そのまま今日の住民全体へ広げることもできません。{cite('gaj','［資料7：調査・刊行の概要］')}</p>
<p>本講座で使う旧町村名は原資料の記録地です。現在の磐田市だけに限定された標本ではありません。地図へ載せる場合も、現行市域へ機械的にまとめず、旧地名の範囲、調査地点の精度、年代を併記する設計が必要です。</p>
''','「けあめ」が載っていない村を、けあめを使わない村として塗り分けられますか？',
'できません。記載がないことは、未採録・選録の結果などとも両立します。不使用を示す調査回答があるかを調べ、未調査・無回答・別形の回答を区別した上で図化します。')

lesson('modality','「だら・ら・ずら」を確信度だけで並べない',
       '推量と聞き手への働きかけを、文の条件から分析する。',f'''
<h3>まず、何に付いている形かを見る</h3>
<p>モダリティは、命題に対する話し手の判断や、聞き手への働きかけに関わる文法的な意味を扱う領域です。遠州の推量表現を考える入口では、語尾だけを切り離さず、名詞述語か動詞述語か、過去か非過去か、否定か肯定か、相手への確認か独り言かを揃えて比べます。</p>
{responses(119895,119897,120660,121425,121426,121427,122225,123745,123747)}
<p>FPJDの磐田市1地点には、名詞述語の「先生だろう」でセンセーダラ、行くのだろうでイクラ・イクダラ・イクズラが記録されています。この組合せだけでも、語尾と述語の接続、調査項目の違いを残して読む理由が分かります。全回答は資料室で確認できます。表は比較のための抜粋で、選んだ形だけが回答されたという意味ではありません。{F}</p>
<p>形態の比較では、イク―ラ、イッタ―ラ、イカン―ラという切り分けを分析の出発点にできます。ラの前に非過去・過去・否定に対応する部分が現れ、推量の部分と時制・肯否を別に捉えられるからです。一方、イクダラ・イカンダラも記録されています。ダを常に意味のない挿入音として消すのでなく、述語との接続や「のだろう」という設問との関係を調べる余地が生まれます。この区切り線は本講座の分析表示で、原データの表記ではありません。</p>
<h3>「多」「少」「ゆ」は、話者人口の比率ではない</h3>
<p>センセーズラの「（ゆ）」は与えた形から引き出した回答、「〈少〉」は話者の使用頻度に関する注です。括弧の種類にも意味があります。これを市民の何％が使うかという数値に読み替えたり、自発的に最初に出た答えと同じ条件で数えたりすると、証拠の性格が変わってしまいます。</p>
<p>門戸ほか（2023）は静岡方言の推量表現を大規模調査で扱い、語形の使用・理解と出生年の関係、場面に応じた意味を検討しています。{M}</p>
<p>本講座の分析では「ダラ＝確信が強い、ズラ＝弱い」と一本の尺度に置く前に、同じ話者に同じ述語で、根拠のある推測・情報を持つ相手への確認・予想が外れた場面を尋ねる調査案を立てます。これは検証のための設計であり、上の抜粋からその結果が判明したという説明ではありません。形の分布と発話の働きをつなぐには、前後の会話が要ります。</p>
''','センセーズラ〈少〉という一記録から、「若者にはズラが通じない」と結論できますか？',
'できません。この注記は特定地点の調査回答に付くものです。若年層の理解を論じるには、年齢や出生年、地域、理解と使用の区別がある別のデータが必要です。')

lesson('grammar','否定・可能・誘いを、形の似た文からほどく',
       '活用の一覧に加え、否定の範囲と会話行為を考える。',f'''
<h3>一つの質問に、一つの答えとは限らない</h3>
{responses(62270,62271,62272,62967,62968,62969,63668,63669,63670)}
<p>FPJDの同地点では「起きない」「来ない」「しない」に、ナイ形・ン形・ヘンを含む形が併記されています。共通語と同形の答えも資料の一部です。珍しい形だけを残すと、調査が記録した併用の姿を落としてしまいます。「多」の注も残した上で、動詞ごとの語幹と後続部分の対応を比較します。{F}</p>
<p>この表から、オキナイ／オキンに対しオキャヘン、コナイ／コンに対しコヤヘン、シナイ／シンに対しシヤヘンという対応が読み取れます。単にナイをヘンへ取り替えるだけでは、記録された形になりません。否定を担う部分と、その前に現れる形の両方が比較の対象になるのです。三つの動詞の観察から始め、他の活用群にも同じ対応があるかを追加データで確かめる、という順序で規則を組み立てます。</p>
<h3>可能表現は、できない理由を揃えて比べる</h3>
{responses(111692,113341,113342,127479,127480)}
<p>能力可能は技量などに関わる可能、状況可能は外的な条件などに関わる可能を区別するための見方です。たとえば「字の読み方を知らない」と「暗くて字が見えない」は、どちらも読めない状態でも条件が異なります。これは違いを考えるための編集部の説明例で、調査票の質問文の引用ではありません。</p>
<p>同地点の「読むことができない」では、能力の項目と状況の項目の両方にヨメナイがあり、状況の項目にはヨメンも記録されています。形が重なることと、意味の区別が存在しないことは同じではありません。提示した状況、言い換えの許容、回答順を含めて検討する必要があります。</p>
<h3>誘いの意味は、相手とのやり取りに現れる</h3>
<p>「行こうよ」のイカザーには「強くさそう場合に使う」と話者の注があります。一方、本サイトの学習語「まい」は編集した会話で誘いを練習しています。この作例から全動詞の規則的な活用を逆算し、機械的に形を生成することは避けます。実際の接続と許容には個別の裏付けが要るためです。</p>
<p>分析の単位は語尾の文字列だけでなく、「誰が何をしようとしている発話か」です。相手が応じる、断る、聞き返すという次の発話まで記録できれば、同じ形が確認・勧誘・意志などのどの働きを担うかを具体的に検討できます。</p>
''','能力と状況の両方にヨメナイがあるので、二つの項目を一行に統合してよいでしょうか？',
'比較の目的では統合しません。同じ形が異なる条件の質問に答えたこと自体がデータです。項目・形・注記を保持してから、共通する用法と異なる用法を考察します。')

lesson('sound','仮名・発音・アクセントを、別の層で読む',
       '「書いてある音」を、そのまま耳で聞いた音にしない。',f'''
<h3>表記を保存することと、音を記述すること</h3>
<p>郡誌の「ならひ」「ちやのこ」のような表記は原表記として保存しています。大きい仮名を現代の小書き仮名へ直したり、旧仮名から当時の実際の音を一意に決めたりすると、原資料にはなかった解釈が混ざります。表記の転記、読みの推定、音声記録の分析を分けて管理する必要があります。{G}</p>
{responses(288,4320,4896)}
<p>FPJDの鏡の回答には［kaŋami］という音声表記があります。ŋは軟口蓋で作る鼻音を表す記号です。一方、「きっ／ぷ」「ふ／う／せ／ん」は拍意識・文字意識を問う項目の表記です。切符には発音は共通語と同様という調査者注があります。斜線を音の高低の境目や実際の休止と読むのは、この項目が何を尋ねたかを見落としています。{F}</p>
<h3>アクセントの体系名は、一語の読み上げ図ではない</h3>
<p>音素・音声の違い、語に属する高低の対立としてのアクセント、文全体のイントネーションは分析の層が異なります。質問文の末尾が上がったとしても、それだけで語のアクセント型が変わったとは言えません。助詞を付けた形や複数の文脈も比較し、語の対立がどこに現れるかを検討します。</p>
<p>平子（2021）は外輪式アクセントを扱う中で、三遠・雲伯と北東北・北部九州の三拍名詞の第六・七類の対応を区別し、歴史的な成立について仮説を提示しています。{H}</p>
<p>この研究の読みどころは、同じ分類名でも下位の対応を確かめる必要がある点です。論文の比較単位である「三遠」を現在の磐田市全住民の発音と同一視することもできません。本講座では語ごとの録音を得ていないため、個別語の高低曲線を作って掲載することはしません。次に必要なのは、地域・話者属性・発話環境を揃えた音声資料です。</p>
''','「きっ／ぷ」の斜線から「きっ」が高く「ぷ」が低いと説明できますか？',
'できません。拍意識・文字意識の調査項目の表記で、アクセントの記号ではありません。語形欄、設問、注記を一緒に読み、別途アクセント資料で確かめます。')

lesson('meaning','同じ形の別の意味を、どう辞書に入れるか',
       '同音異義・多義・語源仮説を分ける、意味論の実習。',f'''
{gunshi('ねこ','かげ','ゆるい','ねんぼう')}
<h3>表記の一致は、同じ語の証明にならない</h3>
<p>於保村の記録には「ねこ＝虹」「かげ＝鍵」「ゆるい＝囲炉裏」があります。現代標準語の猫・影・緩いという見た目の連想を先に置くと、資料の意味を読み違えます。辞書を作るときは、見出しの形だけでなく、対応する対象・品詞・用例・地域・資料の位置を持つ必要があります。{G}</p>
<p>「ねんぼう」は於保村のすりこぎと、下阿多古村辺の股の記録です。二つの意味を一つの見出しの下に並べることは検索には便利でも、単一話者の多義語であると証明したことにはなりません。多義は関連する複数の意味を持つという分析、同音異義は音が同じで別の語という分析です。どちらかを選ぶには、音形、話者の判断、歴史資料、意味の連続性などを検討します。</p>
<h3>語源らしい説明を、語源の確定へ進めない</h3>
<p>龍川村の「かたる＝結婚する」には、語り合うことからの転かという原注があります。この「か」は推測を示す手掛かりです。本サイトでも原注を残し、確定した由来として説明していません。現代の意味からもっともらしい物語を作るだけでは、語の歴史の証拠にならないためです。</p>
<p>辞書編集の実務では、原資料の対応語と編集上の語釈を別の欄に置き、意味ごとに出典を結びます。時代の違う同形を同じページで扱う場合も、年代・記録地・意味を行ごとに示します。検索のための一括表示と、言語学的に同じ語と認定する作業を分けると、便利さと検証可能性を両立できます。</p>
<p>学び舎で追加した資料語48語も、この考え方によるものです。例えば「ねんぼう」の練習では於保村の道具名を選び、別の記録があることを解説に残しています。置換作例は語義を理解する補助であり、語義の成立年代や語源を新たに証明する用例ではありません。</p>
''','「ねんぼう」の二つの意味から、「昔の人は股をすりこぎに見立てた」と説明してよいでしょうか？',
'資料だけでは説明できません。形の一致と別の意味の記録は確認できますが、比喩による意味変化や成立順序は未確認です。そうした説明を仮説にする場合も、追加資料で検証する必要があります。')

lesson('folklore','道具の名前から、暮らしの仕組みへ',
       '民具・食事・仕事のことばを、物と行為に結び付ける。',f'''
<h3>語彙は、暮らしを調べる入口になる</h3>
{gunshi('ねんぼう','せんぼ','ゆるい','ようはん','ようたび')}
<p>すりこぎ、栓、囲炉裏、夕飯、夜なべに対応する名前は、食べる・住む・働くという行為へつながっています。ただし、名前があることから、その地域の全家庭に同じ道具があり、同じ時間に同じ仕事をしたとは言えません。語彙の記録は対象を探す索引になりますが、暮らしの頻度や役割分担の記録を代替しません。{G}</p>
<p>この表を意味の領域で整理すると、ねんぼう・せんぼは手に取る道具、ゆるいは住居内の設備、ようはんは食事、ようたびは時間帯を伴う仕事へ結び付きます。ここでは「ねんぼう」のうち於保村の道具名を扱います。単語を五十音順に置くだけでなく、物―場所―行為―時間という関係で並べると、「同じ道具はどこで、どの仕事に使われたか」という調査の経路が見えてきます。これは資料の語義から組み立てた、本講座の分類です。</p>
<p>東京文化財研究所の「無形文化遺産と民具」は、物の形態だけでなく、呼称、作り手・使い手、使い方などを聞き取り、民具と技術・行為を関連付ける視点を示しています。{T}</p>
<h3>「ねんぼう」を調べるなら、何を記録するか</h3>
{table(['調べる層','具体的な確認事項','そこから考えられる問い'],[
['物','材質、長さ、摩耗、すり鉢との組合せ','同じ呼称が違う形の道具を指すか'],
['ことば','単独の名前、作業中の呼び方、別名、共通語への言い換え','物の名と行為の名がどう結び付くか'],
['行為','何をすり、どの順序で、いつ使ったか','料理・保存・行事との関係があるか'],
['人と伝承','誰から名前や使い方を知ったか、使うか・聞いて分かるか','知識がどの経路で伝わったか']])}
<p>これは本講座の調査設計です。実際に聞き取った結果ではありません。道具の写真だけから用途を決めず、実物、使用の説明、可能なら作業の記録を照合します。家に残る物でも、入手時期と使用時期が違う場合があり、持ち主と使用者が同じとも限りません。</p>
<h3>食事名と時間、仕事名と社会関係を急いで結ばない</h3>
<p>「ようはん＝夕飯」から正確な食事時刻は決まりません。「ようたび＝夜なべ」から特定の作業内容や、性別による分担も決まりません。季節、仕事、灯り、家族構成など別の資料と組み合わせ、聞き取りでは実際に覚えている経験と、年長者から聞いた話を分けます。</p>
<p>このように語を物・行為・伝承経路へ開いていくと、単語帳から民俗学の問いへ進めます。地域の代表的な暮らしと説明する前に、個々の事例を、いつ・どこ・誰の事例かを失わない形で積み重ねることが必要です。</p>
''','郡誌に「ゆるい」があるので、「於保村では1921年に全戸で囲炉裏を使った」と書けますか？',
'書けません。確認できるのは、於保村の語として囲炉裏に対応する記録が掲載されたことです。全戸の設備、使用頻度、採録時点を論じるには、家屋資料や生活記録など別の証拠が要ります。')

lesson('change','変わる方言を、使う・分かる・演じるから捉える',
       '出生年のグラフ、物語の方言、聞き取り計画を読む。',f'''
<h3>世代差のグラフは、時間の記録と同じではない</h3>
<p>門戸ほか（2023）の調査は質問紙とウェブを用い、推量表現の使用・理解と出生年などを分析しています。ツラ・ズラの使用の衰退を論じていますが、図の横軸は出生年です。{M}</p>
<p>たとえば出生年ごとに語形の使用が違うとき、それは一度の調査で異なる出生年の人を比べた結果です。ある年にその語が突然消えたという年表にはできません。同じ人を追う調査、時期を隔てた同条件の再調査、過去資料との比較を加えると、年齢に伴う変化と世代による違いを検討しやすくなります。この方法上の区別が、見かけの時間と実時間の区別です。</p>
<h3>使うこと、理解すること、方言として知ること</h3>
<p>「自分は使わないが祖父母の話なら分かる」「意味は知っていて、冗談のときにだけ使う」という状態は区別する必要があります。これは想定される回答の例です。理解度の調査を使用率と呼び替えず、誰とどこで使うのかも尋ねると、単純な存続・消滅の二択より具体的に変化を捉えられます。</p>
<p>熊谷（2019）は地域を舞台にするドラマや小説を対象に、フィクションで用いられる静岡方言のイメージを検討しています。{K}</p>
<p>作品での方言は、人物像や地域らしさを作るために選択された表現でもあります。作品に出る回数を日常会話の頻度へ置き換えることはできません。本サイトの創作絵札も意味を学ぶための表現であり、当時の実景や実際の話者を再現した資料ではありません。</p>
<h3>自分で小さな調査を組み立てる</h3>
<p>次の表は授業用の記録票です。聞き取りの目的と公開範囲を先に説明して同意を得た上で、氏名などをウェブへ載せることと、分析に使うことを分けて決めます。回答の誘導を避けるため、最初は具体的な場面や実物から名前を尋ね、その後で資料の形を示した反応を別欄へ記録します。資料の形を見せてから出た答えを、自発的な使用例へ混ぜないことが要点です。</p>
{table(['記録欄','残す内容'],[
['条件','調査日、居住歴、相手との関係、質問に用いた場面・実物'],
['最初の回答','資料語を示す前の形、ためらい、言い換え'],
['提示後の回答','提示した語形、理解、自分の使用、誰が使うと認識するか'],
['発話と注記','発話をそのまま残す欄と、調査者の解釈を分ける'],
['利用条件','録音・引用・公開の範囲、確認方法、匿名化の扱い']])}
<p>複数人の結果が揃っても、家族内の小調査を市全体の統計へ広げないことが大切です。問い、標本、記録方法を明らかにすれば、小さな資料にも比較できる価値が生まれます。</p>
''','出生年が新しい人ほど「使わない」と答えたら、若者が年を取っても必ず使わないと言えますか？',
'必ずとは言えません。同じ人を継続して追ったデータではなく、調査時点の出生年集団の差だからです。地域構成・居住歴・回答方法なども点検し、再調査で確かめる問いとして残します。')

sources=[
('gunshi','資料1｜歴史語彙の一次資料','静岡県磐田郡教育会編『静岡県磐田郡誌』1921年、第23章「風俗」第7節「方言」、1242–1254頁。国立国会図書館デジタルコレクション。','https://dl.ndl.go.jp/pid/965680','原画像の選録380記録を使用。各表から見開きの画像と本サイトの記録行へ戻れます。原表記と旧町村名を保持しています。'),
('fpjd','資料2｜全国調査の回答・記号凡例','国立国語研究所「方言の形成過程解明のための全国方言分布調査（FPJD）」、公開データ2025-10-07版。磐田市地点137874-34763。','https://www2.ninjal.ac.jp/hogen/dp/fpjd/fpjd_index.html','国立国語研究所の共同研究「方言の形成過程解明のための全国方言分布調査」の成果に基づく。表の語形・注記は公開回答の抜粋。地域別・世代別の普及率ではありません。'),
('mondo','研究3｜推量表現と変化','門戸巧・峯尾海成・山岸祐己・谷口ジョイ（2023）「大規模調査に基づく静岡方言における推量表現の変異・変化」『人工知能学会全国大会論文集』第37回、1E5-GS-6-04、1–4頁。','https://doi.org/10.11517/pjsai.JSAI2023.0_1E5GS604','本文・図を確認。§3.1の調査方法、§4.2の意味の議論、図1–8の出生年に関する分析を参照。図は転載していません。'),
('hirako','研究4｜アクセント体系の比較','平子達也（2021）「アクセントの分布と機能からみた日本諸語の歴史」日本言語学会第163回大会ワークショップW-3-3、366–371頁。','https://ls-japan.jpn.org/modules/documents/LSJpapers/meeting/163/handouts/ws3/W-3-3_163.pdf','本文・図表を確認。§2.1、368–369頁の外輪式の比較と歴史仮説を参照。個別の磐田の語の高低をこの資料から作成していません。'),
('kumagai','研究5｜フィクションの方言イメージ','熊谷滋子（2019）「フィクションが活用する方言イメージ―なぜ静岡方言は使用されにくいのか？―」『ことば』40、18–35頁。','https://doi.org/10.20741/kotoba.40.0_18','要旨と本文の対象・方法、18–21頁・表1を確認。本講座では作品表現と実生活の使用を区別するために参照しています。'),
('mingu','資料6｜民俗学・民具調査の視点','東京文化財研究所 無形文化遺産部「無形文化遺産と民具」。','https://www.tobunken.go.jp/ich/research/mingu/introduction/','民具と使い方・技術・聞き取りの関連を参照。上の道具の調査票は本講座の編集例で、聞き取り済みの事実ではありません。'),
('gaj','資料7｜分布調査の方法と規模','国立国語研究所『方言文法全国地図』刊行物一覧・概要。','https://www2.ninjal.ac.jp/past-publications/publication/catalogue/gaj_map/index.html','調査時期・地点数・項目数・話者条件を確認。全350図を本講座で再分析したという意味ではありません。')]

glossary=[('語形','音や文字で区別して取り出した形。形が同じでも語や意味が同じとは限りません。'),('語義','ある語に対応させて記述する意味。語釈は資料と編集上の解釈を分けます。'),('異形','同じ語や機能に対応すると分析される、形の異なる現れ。対応の根拠が必要です。'),('等語線','一つの言語的特徴の地理的な分布を区切る線。行政の境界線とは別です。'),('モダリティ','話し手の判断や聞き手への働きかけなどに関わる文法的意味。'),('能力可能・状況可能','技量などと外的条件などを区別して可能表現を調べるための見方。'),('拍','日本語のリズムを考える単位。音節や文字の数と常に一致するわけではありません。'),('アクセント','語を区別する高低などの配置に関わる仕組み。文全体の抑揚と分けて分析します。'),('多義・同音異義','関連する複数の意味と、音が同じ別語という二つの分析。表記だけで決めません。'),('誘導回答','調査側が形を与えるなどして引き出した回答。自発的回答と条件を分けます。'),('見かけの時間・実時間','異なる出生年集団の比較と、時期を隔てた調査の比較という方法上の区別。'),('民具','日常生活や生業などに用いる物。呼称、技術、行為と組み合わせて調べます。')]
toc=''.join(f'<a href="#lesson-{x["id"]}"><span>{n:02}</span><strong>{E(x["title"])}</strong><small>{E(x["deck"])}</small></a>' for n,x in enumerate(lessons,1))
sections=''.join(f'<article class="seminar-lesson" id="lesson-{x["id"]}"><header><p class="eyebrow">講座 {n:02} / SOURCE READING</p><h2>{E(x["title"])}</h2><p class="seminar-deck">{E(x["deck"])}</p></header>{x["body"]}<aside class="seminar-exercise"><p class="eyebrow">考えてみる</p><p>{E(x["question"])}</p><details><summary>資料に戻って答えを確かめる</summary><p>{E(x["answer"])}</p></details></aside><a class="seminar-return" href="#syllabus">8講の一覧へ ↑</a></article>' for n,x in enumerate(lessons,1))
